package org.apache.commons.math3.optim;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.TooManyEvaluationsException;
import org.apache.commons.math3.exception.TooManyIterationsException;
import org.apache.commons.math3.optim.nonlinear.scalar.GoalType;
import org.apache.commons.math3.util.Incrementor;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Unit tests for BaseOptimizer constructor.
 * Since BaseOptimizer is abstract and protected, we use a concrete subclass for testing.
 */
public class BaseOptimizer_BaseOptimizer_TriageGen2Test {

    /**
     * Concrete implementation of BaseOptimizer to allow testing the protected constructor.
     */
    private static class TestOptimizer extends BaseOptimizer {

        protected TestOptimizer(ConvergenceChecker<PAIR> checker) {
            super(checker);
        }

        @Override
        protected PAIR doOptimize() {
            return null;
        }
    }

    /**
     * Mock implementation of PAIR for type compatibility.
     */
    private static class MockPair implements PAIR {
        @Override
        public double getPoint(int index) { return 0.0; }
        @Override
        public double getFunctionValue() { return 0.0; }
        @Override
        public double getGradient(int index) { return 0.0; }
    }

    @Test
    public void testConstructorAndGetters() {
        // Arrange
        @SuppressWarnings("unchecked")
        ConvergenceChecker<PAIR> mockChecker = Mockito.mock(ConvergenceChecker.class);

        // Act
        TestOptimizer optimizer = new TestOptimizer(mockChecker);

        // Assert
        assertNotNull("Optimizer should not be null", optimizer);
        assertEquals("Convergence checker should be correctly assigned", mockChecker, optimizer.getConvergenceChecker());

        // Verify initial states of incrementors via public getters
        assertEquals("Initial evaluations should be 0", 0, optimizer.getEvaluations());
        assertEquals("Initial iterations should be 0", 0, optimizer.getIterations());

        // Note: getMaxEvaluations and getMaxIterations depend on MaxEvalCallback/MaxIterCallback logic.
        // Without knowing the exact implementation of those callbacks, we verify they are initialized.
        // In Commons Math, these usually return a very large value or are set via OptimizationData.
    }

    @Test
    public void testIncrementEvaluationCount() throws TooManyEvaluationsException {
        @SuppressWarnings("unchecked")
        ConvergenceChecker<PAIR> mockChecker = Mockito.mock(ConvergenceChecker.class);
        TestOptimizer optimizer = new TestOptimizer(mockChecker);

        // Act
        optimizer.incrementEvaluationCount();

        // Assert
        assertEquals("Evaluations should increment", 1, optimizer.getEvaluations());
    }

    @Test
    public void testIncrementIterationCount() throws TooManyIterationsException {
        @SuppressWarnings("unchecked")
        ConvergenceChecker<PAIR> mockChecker = Mockito.mock(ConvergenceChecker.class);
        TestOptimizer optimizer = new TestOptimizer(mockChecker);

        // Act
        optimizer.incrementIterationCount();

        // Assert
        assertEquals("Iterations should increment", 1, optimizer.getIterations());
    }
}
